import{_ as o,o as r,c as u,ag as q}from"./chunks/framework.CukOUUOK.js";const h=JSON.parse('{"title":"一个自称代表历史的政党，能不能建立一套让自己被否定的制度？——单一执政组织与民主宪政的制度思想实验","description":"一个真诚相信自己代表历史进步方向、没有特殊利益、也可能犯错的长期执政党，能不能建立一种制度，使自己可以在不被摧毁的情况下承认错误、改变路线，并让失败的路线继续存在？","frontmatter":{"title":"一个自称代表历史的政党，能不能建立一套让自己被否定的制度？——单一执政组织与民主宪政的制度思想实验","categories":"宪法与法治","tags":["法治与宪法","制度","政治思想史","方法论"],"description":"一个真诚相信自己代表历史进步方向、没有特殊利益、也可能犯错的长期执政党，能不能建立一种制度，使自己可以在不被摧毁的情况下承认错误、改变路线，并让失败的路线继续存在？","date":"2026-09-29T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-09-29-party-claiming-to-represent-history.md","filePath":"posts/2026-09-29-party-claiming-to-represent-history.md","lastUpdated":1790928895000}'),n={name:"posts/2026-09-29-party-claiming-to-represent-history.md"};function p(e,t,s,a,i,l){return r(),u("div",null,[...t[0]||(t[0]=[q('<h1 id="一个自称代表历史的政党-能不能建立一套让自己被否定的制度-——单一执政组织与民主宪政的制度思想实验" tabindex="-1">一个自称代表历史的政党，能不能建立一套让自己被否定的制度？——单一执政组织与民主宪政的制度思想实验 <a class="header-anchor" href="#一个自称代表历史的政党-能不能建立一套让自己被否定的制度-——单一执政组织与民主宪政的制度思想实验" aria-label="Permalink to &quot;一个自称代表历史的政党，能不能建立一套让自己被否定的制度？——单一执政组织与民主宪政的制度思想实验&quot;">​</a></h1><hr><h3 id="〇、方法与限度" tabindex="-1">〇、方法与限度 <a class="header-anchor" href="#〇、方法与限度" aria-label="Permalink to &quot;〇、方法与限度&quot;">​</a></h3><p>这篇文章做的是内在批判：先把对方的前提完整地、甚至善意地接受下来，然后追问这些前提能否推出对方想要的结论。它不预设一党制必然失败，也不预设多党制必然成功。</p><p>它也不是论文。文中涉及墨西哥与日本的部分依据公开的制度史事实（来源见文末附注），涉及理论的部分指向几部可查的经典著作，但整体论证仍是规范性的：讨论的是应当如何设计，而非实际上会如何演化。凡是经验判断，都尽量标明它是判断。</p><p><strong>关于&quot;民主宪政&quot;的最低工作定义。</strong> 全文的核心问题是&quot;能不能建立一种民主宪政制度&quot;，而这个复合词如果不加限定，问题就不可证伪。本文采用一个尽量薄、争议尽量小的定义，只包含四个要素：</p><ol><li>最高政治权力受法律约束，且这种约束在最高权力违反法律时仍然有效；</li><li>存在一个不属于任何政治竞争方的最终法律裁判机制；</li><li>若干基本权利不可通过普通的多数程序被削减；</li><li>修改上述三项的程序，其门槛高于通过普通政策的程序。</li></ol><p>注意这个定义里没有出现&quot;多党&quot;，也不要求普选——一个由选举人团、地方议会或党内代表大会产生的最高权力，只要满足上述四条，在本文的意义上就构成宪政。是否同时构成&quot;民主&quot;，取决于最高权力的可撤销性，这正是第十二节要处理的问题。采用薄定义的代价是，本文无法回答&quot;什么样的民主是好的&quot;；它只能回答&quot;什么样的安排在逻辑上自洽&quot;。</p><p>真正想问的问题只有一个：</p><blockquote><p>一个真诚相信自己代表历史进步方向、真诚相信自己没有特殊利益、真诚承认自己可能犯错的长期执政党，能不能建立一种制度，使自己可以在不被摧毁的情况下承认错误，在不发生政治清算的情况下改变路线，并让失败的路线继续存在、在未来重新获得多数？</p></blockquote><p>如果答案是可以，我们就有可能构想一种既不同于美国总统制、也不同于传统多党竞争的民主宪政。如果答案是不可以，就必须解释：为什么路线之争最终总会变成你死我活的权力之争。</p><hr><h3 id="一、把前提完整地交给对方" tabindex="-1">一、把前提完整地交给对方 <a class="header-anchor" href="#一、把前提完整地交给对方" aria-label="Permalink to &quot;一、把前提完整地交给对方&quot;">​</a></h3><p>假设有一个国家，长期由一个政党领导。这个政党相信历史存在某种进步方向，也相信自己的纲领比其他可能的路线更接近这个方向。它同时相信四件事：自己不是为少数人的私人利益而存在；长期执政能保证政策连续性，避免政治竞争造成的短期主义和社会撕裂；人和组织都会犯错，所以任何具体路线、政策和领导人都不能被假定永远正确；它不需要照搬任何外国制度，可以发展出自己的民主形式。</p><p>我们暂时完全接受这些前提。甚至进一步假设：这个党是真诚的。它真的认为自己没有特殊利益，真的相信自己在为人民服务，也真的承认自己可能犯错。</p><p>那么问题就出现了：<strong>如果它真的承认自己可能犯错，它准备怎样让自己被证明是错的？</strong></p><p>注意，这不是一个道德问题，不是问它有没有勇气。这是一个制度能力问题：它手里有没有一套可运转的机制，能在特定条件下产出&quot;我们错了&quot;这个结论，并且产出之后系统不崩溃。把问题从&quot;敢不敢&quot;改写成&quot;能不能&quot;，全文的论证方向就变了——前者指向品格，后者指向机构、程序和资源。品格无法被设计，机构可以。</p><hr><h3 id="二、认识论的裂缝" tabindex="-1">二、认识论的裂缝 <a class="header-anchor" href="#二、认识论的裂缝" aria-label="Permalink to &quot;二、认识论的裂缝&quot;">​</a></h3><p>假设这个党认为：历史存在客观规律，而社会主义代表历史进步方向。即使完全接受这个判断，也不能自动推出&quot;这个党永远知道哪条具体路线才是正确的&quot;。</p><p>这里其实有三个层次完全不同的命题，混在一起用就会出问题。&quot;历史存在方向&quot;是关于历史的哲学判断；&quot;我们知道历史正在往哪里走&quot;是认识论判断；&quot;我们现在提出的这项政策符合历史方向&quot;则是具体的经验判断。三者之间没有任何逻辑通道。第一个命题为真，推不出第二个；第二个为真，也推不出第三个——因为即便知道方向，从方向到具体政策的映射永远是一对多的。</p><p>一旦混同，就会出现一个自我闭合的循环：我们代表历史进步方向，所以我们的路线是正确的；因为我们的路线是正确的，所以它代表历史进步方向。在这个循环里，&quot;历史&quot;不再是检验路线的标准，而变成了路线为自己储存合法性的仓库。实践检验也就只剩一种可能的输出：实践必须最终被解释为证明自己正确。</p><p>这一段论证有一个明确的智识来源，应当点出来。卡尔·波普尔在《研究的逻辑》（<em>Logik der Forschung</em>, 1934；英译《科学发现的逻辑》, 1959）中提出的可证伪性标准，说的正是这件事：一个理论如果与任何可能的观察都相容，那它就没有经验内容，因为没有任何事态能够反驳它。&quot;实践是检验真理的唯一标准&quot;如果被解释成&quot;实践最终会证明我们正确&quot;，它就变成了一个与任何可能的事态都相容的命题——它永远为真，因此什么也没有说。</p><p>波普尔后来在《开放社会及其敌人》（1945）里把这个逻辑推向政治，并在《猜想与反驳》（1963）中发展为一套关于知识增长的方法论。其中最关键的一步是他对传统政治哲学的改写：他认为&quot;谁应当统治&quot;这个问题问错了，因为它假定存在一个可识别的最优统治者，而真正该问的是&quot;怎样组织政治制度，才能使糟糕或无能的统治者不会造成太大的损害&quot;。本文的核心问题与这一改写在结构上同构。本文的增量在于把它落到机构与资源层面，并用两个真实政党做检验——而检验的结果，如第九节所示，并不完全支持波普尔式的乐观。</p><p>必须强调，指出这道裂缝并不削弱历史理论，反而使它成立。一个严肃的历史理论应当允许这种可能：历史可能有方向，但我们可能误判方向。只有在这种可能性被制度性地承认之后，&quot;实践检验&quot;才有内容。</p><p>所以，真正有意义的实践检验，必须允许&quot;我们的路线错了&quot;这句话在制度内被说出口、被记录下来，并且说出口的人不因此付出代价。而这句话一旦成立，问题就从哲学进入制度，因为紧接着还有更难的一句：<strong>既然我们的路线错了，那么谁来纠正我们？以什么程序纠正？纠正之后原来的路线支持者怎么办？</strong></p><hr><h3 id="三、反向推论-以及它跳过的那个前提" tabindex="-1">三、反向推论，以及它跳过的那个前提 <a class="header-anchor" href="#三、反向推论-以及它跳过的那个前提" aria-label="Permalink to &quot;三、反向推论，以及它跳过的那个前提&quot;">​</a></h3><p>假设这个党进一步提出：&quot;我们没有自己的特殊利益。&quot;</p><p>这个命题有一种善意的解释：它不把政党自身的利益置于人民利益之上。而从这个前提出发，最自然的制度推论是什么？</p><p>多数人会这样推：因为它没有特殊利益，所以它长期执政没有问题。这个推论本身没错，但它是弱的，而且方向单一。同一个前提还允许一个严格得多的推论：</p><blockquote><p>既然它没有特殊利益，那么它应该最不害怕人民监督、批评甚至否定它。</p></blockquote><p>理由是：如果一个组织真的相信自己的利益与社会整体利益一致，那么&quot;失去执政地位&quot;对它而言就不构成利益损失。人民说&quot;你错了&quot;，它应当回答&quot;请证明我们错了&quot;；人民说&quot;我们不同意这条路线&quot;，它应当回答&quot;让不同路线竞争&quot;。</p><p>这形成了一个颇有意思的结构：<strong>越是相信自己没有特殊利益，越应该允许人民拥有最终否定自己的权利。</strong> 反之，如果否定权是不可想象的，那就等于承认政治存续本身是一项特殊利益——而这与前提矛盾。</p><p><strong>但这里有一个跳跃，必须承认。</strong> 上面这段推理混用了两个不同层次的命题。&quot;我们没有自身私利&quot;是关于组织<strong>动机</strong>的陈述；&quot;我们下台不会损害公共利益&quot;是关于<strong>因果</strong>的陈述。前者推不出后者。</p><p>一个真诚的组织完全可以同时持有这两个判断：我们没有私利，<strong>而且</strong>我们的持续领导是公共利益得以实现的必要条件——否则会出现政策中断、社会撕裂、外部乘虚而入。在这个版本里，拒绝交出权力不是私利，而是一种责任判断。它可能是错的，但它不是不诚实的。</p><p>所以反向推论真正需要的前提不是&quot;没有特殊利益&quot;，而是强得多的一条：</p><blockquote><p>我的持续执政，在任何时候都不是公共利益得以实现的必要条件。</p></blockquote><p>这条前提有一个麻烦的性质：几乎不可证伪。任何一次危机都可以被解释为&quot;幸好我们还在&quot;，任何一次平稳交接都可以被解释为&quot;因为我们提前安排好了&quot;。</p><p>面对这条前提有三条路，诚实程度各不相同：</p><p><strong>第一条，把它当作规范承诺。</strong> 即&quot;我们认为自己的持续领导本身就构成公共利益的组成部分&quot;。这是一个合法的立场，历史上许多政治组织都持有它。但它是信仰声明，而非从&quot;没有特殊利益&quot;推出的结论，因此它不能借用后者的逻辑力量——你不能一边说&quot;这个推论来自我们的无私&quot;，一边在关键一步偷换成&quot;这个推论来自我们的信念&quot;。</p><p><strong>第二条，把它当作经验命题并接受检验。</strong> 那就必须有检验程序，而检验程序必然意味着存在一个能产出否定结果的机制。一旦走这条路，本文第十二节讨论的&quot;闸门九&quot;（执政资格可撤销）就从可选项变成必选项——因为如果最高执政资格不可撤销，&quot;持续执政是否必要&quot;这个命题就永远无法被检验，它自动退回第一条路。</p><p><strong>第三条，承认这条前提无法检验，因此拒绝检验。</strong> 这是现实中最常见的选择。它的代价是：整个&quot;没有特殊利益&quot;的论证随之失去对制度设计的约束力，因为它无法被任何反例触动。一个不能被任何证据动摇的承诺，在制度设计中等于没有承诺。</p><p><strong>本文采取第二条，并且明确它的地位：它不是从前提出发的推论，而是一个附加的规范选择。</strong> 从这里往下的所有论证都建立在这个附加选择之上。承认这一点会让本节的修辞力量减弱一些，但换来的是它不再有一个十秒钟就能被找到的破口。这是一个值得做的交换。</p><p>需要预先说明一件事，以免读者在后面产生困惑：<strong>第三节的选择是本文的规范立场，第十一节的分析并不为这个立场辩护。</strong> 第十一节会认真考察拒绝闸门九的制度形态，并承认它可能长期稳定、甚至可能在很长时间里表现优越。那不是本文的自我反驳，而是在描述：拒绝这个立场的人实际会得到什么，以及账单以什么形式、在什么时候到期。一个只描述自己支持的方案、不描述被拒绝方案的实际后果的理论，在制度设计上是无用的。</p><hr><h3 id="四、两个必须切开的概念" tabindex="-1">四、两个必须切开的概念 <a class="header-anchor" href="#四、两个必须切开的概念" aria-label="Permalink to &quot;四、两个必须切开的概念&quot;">​</a></h3><p>政治制度经常把注意力放在&quot;有没有竞争&quot;上。但真正决定制度性质的是<strong>失败的定义</strong>。</p><p>设想党内有两条路线。A 路线主张更重视效率，B 路线主张更重视平等。A 获得多数，B 失败。接下来发生什么？这里存在两种完全不同的制度。</p><p>第一种是不可逆的路线斗争。A 获胜，B 成为&quot;错误路线&quot;，B 的政治影响力下降，B 的支持者逐渐失去组织空间，若干年后 A 路线成为唯一合法的解释框架。在这种制度下，如果实践证明 A 出了严重问题，B 要重新出现就必须借助一次新的政治转折——通常是最高领导层的更替，甚至是历史叙事的整体重写。纠错成本极高，而且纠错本身会消耗组织的合法性储备。</p><p>第二种是可逆的路线竞争。A 获胜，B 成为少数，但 B 仍然合法存在：可以组织讨论、提出纲领、参加下一轮竞争。如果 A 的政策效果不好，下一次 B 可能重新获得多数并执政，A 退居少数。再过若干年，如果 B 也出问题，A 仍然可以回来。</p><p>这两种制度的差别，可以用两组概念精确刻画。</p><p><strong>长期执政不等于永久执政。</strong> 长期执政是&quot;你长期赢&quot;，永久执政是&quot;你无论输赢都不能下台&quot;。前者与民主完全兼容——一个政党连续几十年赢得竞争，并不必然意味着这个体系不民主。后者直接触及人民主权的边界。真正的问题从来不是&quot;你赢了多久&quot;，而是&quot;如果有一天你输了，你承不承认结果&quot;。</p><p><strong>失败不等于消失。</strong> 这是所有民主制度最深层的技术之一。它不保证系统永远正确，它只做一件事：让错误变得便宜。</p><p>亚当·普热沃尔斯基对民主的定义与此几乎重合，而且比本文的说法更精炼：民主是这样一个制度，其中政党会<strong>输掉选举</strong>——他特别强调，这个定义的关键不在&quot;选举存在&quot;，而在&quot;输了之后还能再来&quot;。他把这种状态称为&quot;制度化的不确定性&quot;：结果不确定，程序确定；没有人知道下一轮谁会赢，所有人都知道下一轮一定会来。他给出的核心论证是一个博弈论式的计算：失败方之所以接受失败，是因为它算得出等待的成本低于反抗的成本——前提是它确信自己还有下一次。</p><p>这个论证恰好把本文第五节要解释的现象说清楚了：<strong>如果失败方算不出&quot;下一次&quot;在哪，等待的成本就变成无穷大，反抗就是唯一理性选择。</strong></p><p>由此也得到一个关于制度压力测试的判断：政治制度真正的压力测试从来不是&quot;赢家会不会接受自己赢了&quot;，而是&quot;赢家会不会接受自己输了&quot;。前一种情况不需要任何制度成本，后一种情况需要全部制度成本。</p><hr><h3 id="五、路线斗争为什么总是走向你死我活" tabindex="-1">五、路线斗争为什么总是走向你死我活 <a class="header-anchor" href="#五、路线斗争为什么总是走向你死我活" aria-label="Permalink to &quot;五、路线斗争为什么总是走向你死我活&quot;">​</a></h3><p>因为在高度集中的政治体系中，&quot;路线&quot;从来不是一个纯粹的政策观点。它同时连接着人事、组织、资源、权力、政治合法性、历史评价和个人政治生命。于是一条滑坡就出现了：反对一项政策，很容易变成反对一套路线；反对一套路线，很容易变成不服从组织决定；不服从组织决定，很容易变成政治立场问题。一旦形成这种结构，输掉路线之争就意味着失去的不只是一次政策表决，而是整个政治身份。</p><p>这时双方都清楚一件事：输了以后，我可能没有下一次。而正是这个认知，而不是分歧本身的严重程度，决定了斗争的烈度。所以制度设计最应该解决的不是&quot;怎样避免分歧&quot;——分歧无法避免，也不应该避免——而是&quot;怎样让分歧存在而不必走向你死我活&quot;。</p><p>二十世纪七十年代中国的政治转折，是这个机制的一个<strong>例证</strong>——请注意是例证，不是证明。单个案例无法支撑一个一般机制，而且这个案例混杂了群众动员、继承斗争、国际环境等多个变量，无法从中干净地分离出制度因素。下面把它作为例证使用，第九节将用三个案例（其中一个是反例）做对照，第十节提供一个可用于横向比较的理论工具。</p><p>1976 年 10 月&quot;文化大革命&quot;结束，&quot;四人帮&quot;被粉碎。后来形成的历史决议将&quot;文化大革命&quot;定性为由毛泽东发动和领导的严重错误，认为个人专断逐步损害民主集中制，党中央未能及时纠正相关错误；决议同时详细叙述了 1974 至 1976 年间江青、张春桥、姚文元、王洪文集团与其他政治力量之间的冲突，以及此后政治路线和政策方向的转变。</p><p>值得追问的是：为什么这次路线转换需要通过如此剧烈的政治断裂来完成？流行的解释是&quot;当时不具备这样的条件&quot;。这个解释等于没有解释。要说清机制，需要指出三个具体的制度缺失。</p><p>第一，接班规则不独立于现任者的个人意志。当路线的合法性最终来源于最高领导人个人的认可，而非任何可预期的程序时，&quot;路线正确&quot;与&quot;获得信任&quot;就无法区分，路线竞争也就自动变成信任竞争，而信任竞争的失败者没有制度化的退路。</p><p>第二，没有任何为组织化少数派保留空间的场所。少数意见可以以个人形式存在（写材料、上书、检讨后被安排闲职），但不能以稳定的、公开的、有纲领的组织形式存在。没有组织形式，就没有&quot;下一次&quot;的物质载体——路线不能像人一样等待时机，它需要机构来承载。</p><p>第三，不存在任何外部裁判。当争议双方都诉诸同一个权威来源时，裁决只能由这个权威来源内部的力量对比决定，而力量对比的裁决结果天然是排他性的。</p><p>这三个缺失合起来，解释了此后的纠错为什么必须采取&quot;重新定性历史&quot;的形式：前一条路线的组织载体已经被彻底清除，它没有下一次，所以唯一的纠错途径就是宣布它从头到尾是错的。</p><p><strong>这里必须处理一个对立的、而且更主流的解释。</strong> 我在早期稿中写&quot;清算必然消耗合法性&quot;，这个说法过强。通行的评价恰恰相反：1981 年的历史决议通过展示自我纠错能力<strong>重建</strong>了合法性；它本身就是一个&quot;非解体式纠错&quot;的成功样本——组织主体存活，路线彻底转向，系统没有崩溃，而且随后的几十年里这套转向被证明极其有效。这个评价是对的，本文接受它。</p><p>但接受它之后，可以得到一个更精确的表述：</p><blockquote><p>清算式纠错在第一次是<strong>转化</strong>，第二次才是<strong>消耗</strong>。</p></blockquote><p>1981 年的决议之所以成功，是因为它动用的是一种不可再生的资产：一个仍然在世的开创世代所共享的直接记忆。参与决议的人，以及被决议说服的人，绝大多数亲身经历过 1966 至 1976 年。这份共同记忆使得&quot;彻底否定一段历史&quot;与&quot;保住这个组织&quot;这两件看似矛盾的事可以同时完成——因为否定的对象是所有在场者都能辨认的对象。</p><p><strong>这个机制有一个更强的竞争解释，必须处理。</strong> 决议的成功可能主要不来自共同记忆，而来自随后几十年持续的绩效改善：生活水平提高、社会流动扩大、国家能力增长。如果主导因素是绩效，那么&quot;清算式纠错不可制度化&quot;这个结论就被削弱了，因为绩效是可以再生产的，而记忆不能。</p><p>两者如何区分？反事实是清晰的：<strong>如果 1981 年之后没有出现绩效改善，决议能否单独撑住合法性？</strong> 我的判断是不能，而这恰恰说明两种解释并不冲突，它们处理的是不同的时间尺度。共同记忆解决的是<strong>决议当时</strong>的问题——它让&quot;否定一段历史&quot;与&quot;保住这个组织&quot;在那一刻可以被同时接受；绩效解决的是<strong>决议之后</strong>的问题——它让转向获得持续的正当性供给。前者是一次性的，后者是可再生产的。</p><p>所以更准确的表述是：清算式纠错<strong>启动</strong>时需要一笔不可再生的资产（共同记忆），<strong>维持</strong>则依赖一笔可再生产的资产（绩效）。这削弱了我原先&quot;不可制度化&quot;的说法的强度，但没有取消它——因为启动条件仍然不可复制。一个第二代之后才犯错、且绩效恰好同时恶化的系统，将同时缺少两笔资产。这个组合不是不可能，而且在历史上出现过。</p><p>这个案例的真正启示因此是：<strong>在缺乏可逆性机制的系统里，纠错只能以清算的形式出现；清算式纠错可以成功一次，但它的成功条件无法被制度化为可重复使用的程序。</strong> 1981 年的决议是一份高难度的政治文件，它成功地把一次性资产兑换成了数十年的转向空间——但兑换只能做一次。</p><p>由此也就得到一个比&quot;路线斗争能力&quot;更值得追求的目标：<strong>更低烈度、且可以重复使用的路线更替机制。</strong></p><hr><h3 id="六、制度实验-党内路线竞争的九道闸门" tabindex="-1">六、制度实验：党内路线竞争的九道闸门 <a class="header-anchor" href="#六、制度实验-党内路线竞争的九道闸门" aria-label="Permalink to &quot;六、制度实验：党内路线竞争的九道闸门&quot;">​</a></h3><p>假设这个国家坚持单一执政党。那么可以做一个大胆的实验：党仍然只有一个，但党内允许形成长期、合法、公开、组织化的不同政治路线。党不再是一个只有一套意见的整体，而是一个巨大的政治共同体，里面允许 A、B、C 三条路线并存。它们都承认宪法、都承认基本制度、都承认和平竞争规则，但对经济、社会、地方治理、福利、市场、教育、文化、外交等问题持有明显不同的纲领。政治竞争于是不再发生在党与党之间，而发生在路线与路线之间。</p><p>这是第一步，但它远远不够。一个只允许&quot;你可以说不同意见&quot;却不允许&quot;你可以组织起来支持这种意见&quot;的制度，其路线竞争是脆弱的。要把这一步做实，至少需要九道闸门：</p><ol><li>党可以长期执政，但不能预先宣布自己永远正确。它只能说&quot;我们认为自己的路线更正确&quot;，不能说&quot;历史已经证明我们永远正确&quot;。</li><li>路线必须能够公开竞争，不能只有一个&quot;正确答案&quot;。</li><li>少数路线必须合法存在，失败不是犯罪。</li><li>失败路线必须能够重新竞争，今天的少数不意味着永久的少数。</li><li>领导人必须能够被和平替换，不能把个人与制度绑定。</li><li>政治程序不能由当权路线自己决定，否则民主规则会随胜负被改写。</li><li>党内竞争必须在事实上（而非仅在纸面上）不受现任领导层控制。</li><li>党外社会必须拥有独立空间，因为党员不是人民的全部。</li><li>人民必须保留最终纠错权，即最高执政资格可被撤销。</li></ol><p>前三道是入门条件；六、七、八决定成败；第九道最含糊，也最关键，本文留到第十二节单独处理，因为它是全文论证强度最不均匀的地方。这里先展开三组最难的闸门，它们涉及的都是资源问题，不是意愿问题。</p><p><strong>第六、第七道：谁裁判选举。</strong> 如果执政的多数派同时掌握选举规则、候选人提名、议程设置、党章解释、干部任命、会议程序和纪律处分，那么民主程序完全可能被设计成一种精巧的形式：你可以投票，但你只能从我们允许你选择的人里面投票。这时候形式上有民主，实质上只是&quot;在既定范围内选择管理者&quot;。罗伯特·米歇尔斯在 1911 年的《政党社会学》中提出的&quot;寡头铁律&quot;讲的正是这件事：大规模复杂组织必然产生专职领导层，而领导层掌握的三样东西——组织机器的日常运作权、信息与通讯渠道、以及对外代表权——使其逐渐获得相对于普通成员的自主性，最终组织的&quot;目的&quot;会被组织的&quot;存续&quot;所置换。米歇尔斯的论证是经验性的（基于德国社民党的组织史），结论是决定论的，而决定论部分后来被大量修正，现代组织研究更倾向于把它当作一个需要条件限定的趋势，而非定律。但它描述的三项控制权，恰好就是第六、第七道闸门要处理的东西。</p><p><strong>第三、第四道的物质基础：少数派靠什么活着。</strong> 这是所有党内民主讨论集体沉默的地方。一个少数派要作为组织存在，需要经费、办公场所、传播渠道和干部培养机制。这些资源从哪来？三条路，每条都有代价：</p><ul><li><strong>由党的公共预算分配</strong>——那么分配权在现任多数派手里，少数派可以被逐步饿死。这不是假设，这是可预期的默认结果，因为没有任何当权者有动机资助自己的竞争者。</li><li><strong>由外部捐款支持</strong>——那么派别立刻被外部利益俘获，&quot;党内竞争&quot;实际上变成&quot;党外资本的竞争通道&quot;。</li><li><strong>由成员自筹</strong>——那么只有具备经济资源的成员才能参与，派别会向门阀化演变，路线分歧会逐渐被家族与人际网络所替代。</li></ul><p>这是一个三难。而政治学中恰好有一个理论直接处理它：卡茨与梅尔在 1995 年提出的&quot;卡特尔政党&quot;命题。他们的观察是，当政党日益依赖国家资源而非成员 dues 与社会捐助时，政党之间会形成一种默契的合谋——共同提高进入门槛、共同分享国家补贴、共同把自己从社会代理人改造为国家代理人。结果是竞争形式上保留，实质上被在位者联盟接管。这正是上面第一条路的失败模式，而且它给出一个反直觉的结论：<strong>用公共资金&quot;公平&quot;地资助各派，可能比让各派自己找钱更快地杀死竞争</strong>，因为它把在位者的合谋制度化了。</p><p>日本的派阀政治同时演示了第二条和第三条路的后果：派阀高度依赖企业政治献金，最终演化为 2023 至 2024 年的&quot;黑金&quot;丑闻，导致多个主要派阀解散；派阀的人事与资金网络长期由政治世家维系，形成了另一形态的门阀化。这不是执行不力，而是结构使然。任何党内路线竞争制度都必须正面回答这个问题，而历史上所有回答都带来了副作用。</p><p><strong>第八道：党内民主的天花板。</strong> 假设这个党有几千万成员，党内有 A、B、C 三条路线，它们自由竞争。很好。但是没有加入这个党的那些人怎么办？他们是不是只有&quot;接受党内竞争结果&quot;的义务？</p><p>如果是，那么这个制度的民主性存在一个无法在党内解决的缺口：党内民主不等于人民主权。党员是公民的一部分，党不能自动等同于全社会。所以一个一党制国家如果真想建立民主宪政，党外社会至少需要具备某种真实的自主性——公民可以表达不同意见，新闻可以调查权力，学者可以提出不同理论，社会组织可以形成，工人、企业和专业群体可以表达利益，公民可以挑战行政决定，地方社会可以形成不同的政策偏好。</p><p>否则所谓民主最终只是&quot;一个大型政治组织内部的民主&quot;，而非&quot;整个社会对政治权力的民主控制&quot;。这一点在政党研究中是常识：现代政党既是民主代表机制的一部分，又可能成为权力集中的组织载体，这种双重性正是问题的核心。</p><hr><h3 id="七、反方的最强形式" tabindex="-1">七、反方的最强形式 <a class="header-anchor" href="#七、反方的最强形式" aria-label="Permalink to &quot;七、反方的最强形式&quot;">​</a></h3><p>到这里，一个诚实的思想实验必须停下来，让反对意见用它最强的形式说话。前面所有的推论都建立在一个未经检验的假设上：<strong>可替代性会带来纠错。</strong> 这个假设有四条有力的反驳。</p><p><strong>第一条，纠错不是免费的，它有时比错误更贵。</strong> 政策反复会损害长期投资预期。能源结构、基础设施、外交同盟、产业培育这些领域需要跨代际的承诺，而每一次政权更替都可能重置承诺。日本民主党 2009 至 2012 年的执政是现成的例子：三年之内首相三度更替，普天间基地搬迁承诺无法兑现，最终在 2012 年下野。这段经历对日本政治的长期影响之一，是让相当一部分选民和官僚系统对&quot;政权轮替&quot;本身产生了怀疑。可替代性买来了纠错能力，也买来了不稳定性，这两者是同一枚硬币。</p><p><strong>第二条，民主竞争产出的不是&quot;更正确的路线&quot;，而是&quot;更能动员多数的路线&quot;，这两者在很多情况下背离。</strong> 如果一个社会的多数偏好本身就是短视的、民粹的或被情绪驱动的，那么制度化竞争只会更高效地生产错误决策，而且因为它带有民主合法性，纠错反而更难。这条反驳最厉害的地方在于：它不接受&quot;竞争产生纠错&quot;这个前提，因此无法用前面任何一道闸门来回应。本文对它的回答只能是承认：闸门体系不提供正确性，只提供可修正性；如果一个社会反复选择同一种错误，这套制度不会救它，只会让它在错误里换人。第九节将要引入的意大利案例，是这条反驳最完整的实证版本。</p><p><strong>第三条，在深度分裂的社会里，开放竞争可能把族群、宗教或地域认同政治化，从而把制度化的可替代性变成制度化的分裂。</strong> 对一个尚在完成国家建构的社会，这个风险不是理论上的。本文第十二节会承认，这条反驳足以构成对闸门九的实质性限制。</p><p><strong>第四条，竞争性选举天然为外部势力提供介入通道</strong>——政治献金、媒体、非政府组织都是可操作的接口。对一个面临真实外部压力的后发国家，这是一个安全考量，而不只是一个借口。</p><p>这四条反驳，我认为第三条和第四条在特定条件下成立，第一条部分成立，第二条最难处理。</p><p>它们合起来指向一个结论：<strong>这套制度不是免费获得优势，而是在交换风险。</strong> 单一组织保持高度连续性，理论上可以减少频繁轮替，有利于长期政策一致性；但高度连续也意味着错误一旦形成，纠正所需的时间更长。多元竞争可能产生党争、极化和短期主义；但竞争也提供了一种外部纠错压力。</p><hr><h3 id="八、非替代性纠错-它们能做什么-不能做什么" tabindex="-1">八、非替代性纠错：它们能做什么，不能做什么 <a class="header-anchor" href="#八、非替代性纠错-它们能做什么-不能做什么" aria-label="Permalink to &quot;八、非替代性纠错：它们能做什么，不能做什么&quot;">​</a></h3><p>上面四条反驳背后还有一个更根本的质疑：<strong>为什么纠错必须通过&quot;政治替代性&quot;？</strong> 独立的技术官僚系统、地方政策试验、协商机制、独立媒体与司法、小范围试点——这些不也能纠错吗？在很多领域它们纠错得更快、更专业、成本更低。</p><p>这个质疑是有力的，而且它有真实的经验支撑。过去几十年里最有效的政策纠错机制之一，恰恰不是选举，而是分级制的政策试验：地方先行先试，中央观察、比较、择优推广。这套装置在产业、财政、环保、社保领域调整速度远快于任何议会程序，而且完全不需要政党轮替。</p><p>但这些机制共享一个结构性特征：<strong>它们都是由那个可能需要被纠正的权威授权运行的。</strong> 技术官僚是被任命的，试点是被批准的，媒体是被许可的，法官是被任命的，协商的议题是被设定的。只要错误发生在政策域内，这些通道都能正常工作；一旦错误发生在&quot;由谁统治&quot;这个域，它们会同时失去独立性——因为它们独立性的来源正是那个出错的权威。</p><p>这就是为什么它们是可替代性的<strong>补充</strong>，而非替代品。它们能纠正政策错误，不能纠正统治错误。</p><p>而且本文第十一节将会承认，前八道闸门足以吸收绝大多数日常冲突。这等于承认：可替代性不是通用纠错机制，它是<strong>尾部风险保险</strong>。这个定位应当明确写下来，因为它带来一个反直觉的推论——</p><p><strong>这份保险在政治上永远会被系统性地低估，而且低估不是因为判断力差。</strong> 它的成本是持续、可见、当期支付的：政治不确定性、政策反复、派系开销、外部介入风险。它的收益是偶发、不可见、反事实的：一次没有发生的崩溃。任何政治体系在权衡这两种账目时都会偏向削减保险，因为削减的收益立刻可兑现，而削减的代价属于一个还没有到来的未来，并且如果它永远不到来，削减就是净赚。</p><p>所以第七节列出的四条反驳，无法通过&quot;更仔细地权衡&quot;来解决。<strong>权衡的天平本身就是倾斜的</strong>，倾斜的方向由账目的时间结构决定，不由参与者的智慧决定。</p><p>但这个论证需要一个上限，否则它过强了。<strong>其他系统的失败是可见的。</strong> 苏联解体、墨西哥七十一年、日本 1993 年，这些都是公开的样本，决策者并非全然在黑暗中权衡。所以低估是真实的，但它的程度由一个具体变量决定：<strong>可借鉴的失败样本有多少，以及这些样本的可得性有多高。</strong></p><p>由此引出一个不太舒服的推论：<strong>比较样本本身是一种稀缺的公共品。</strong> 一个政治体系能够多大程度上克服保险低估的倾向，取决于它对其他体系失败方式的认知有多清晰——而这种认知通常依赖公开的学术讨论、可获取的外国制度史、以及不受限制的媒体调查。对比较材料的封锁，因此不只是意识形态管理的副产品，它同时也是有限可逆制最有效的自我保护手段之一：如果失败样本不可见，保险的低估就从系统性偏差变成了近乎绝对。</p><p>这也给出了一个可操作的判断标准，用于评估任何自称&quot;我们不需要那种保险&quot;的体系：<strong>看它对外部失败案例的讨论有多开放。</strong> 开放程度越低，其&quot;不需要&quot;的判断就越不可能建立在知情权衡之上。</p><hr><h3 id="九、案例检验-墨西哥、日本-以及一个反例" tabindex="-1">九、案例检验：墨西哥、日本，以及一个反例 <a class="header-anchor" href="#九、案例检验-墨西哥、日本-以及一个反例" aria-label="Permalink to &quot;九、案例检验：墨西哥、日本，以及一个反例&quot;">​</a></h3><p>上面都是规范推演。要让它落地，需要真实的对照样本。二十世纪提供了三个，其中第三个是反例，而它可能是最重要的那个。</p><h4 id="_9-1-墨西哥革命制度党-分期-而不是当作一个同质制度" tabindex="-1">9.1 墨西哥革命制度党：分期，而不是当作一个同质制度 <a class="header-anchor" href="#_9-1-墨西哥革命制度党-分期-而不是当作一个同质制度" aria-label="Permalink to &quot;9.1 墨西哥革命制度党：分期，而不是当作一个同质制度&quot;">​</a></h4><p>该党成立于 1929 年，前身是国民革命党，1938 年改组为墨西哥革命党，1946 年定名革命制度党，从 1929 年到 2000 年连续执政七十一年。把七十一年当作一个均质制度来分析是错的——它在 1988 年前后几乎是两个不同的系统。</p><p><strong>1929—1988：霸权党体制。</strong> 制度形态有几个鲜明特点。宪法自 1928 年修宪后规定总统任期六年、终身不得连任，这条规则被严格执行了近一个世纪，在拉美军事政变频发的背景下极其罕见。党内实行职团主义结构，设工人部、农民部、人民部三大部门，通过全国性的工农与民众组织把社会各阶层纳入体制内，使利益冲突在党内消化。它在很长一段时间里创造了政治稳定与持续增长，把军队排除出政治。</p><p>但接班规则是这套系统最脆弱的一环：总统候选人由现任总统个人指认（俗称&quot;指定制&quot;），而&quot;由谁来指认指认者&quot;没有任何程序回答。用第六节的闸门对照，这一时期的状态是：<strong>闸门五（领导人可替换）在个人层面刚性极强，闸门六、七（程序独立）完全关闭，闸门八（党外社会空间）被职团结构大幅收窄，闸门九（执政资格可撤销）不存在。</strong></p><p>亨廷顿衡量政治制度化的四个维度是适应性、复杂性、自主性与内聚力。以此衡量，这一时期的 PRI 在复杂性（三大部门、多层组织）与内聚力（七十年未分裂执政）上得分很高，在自主性上得分很高（政党凌驾于任何单一社会集团之上），但在<strong>适应性</strong>上有一个致命缺陷：适应性的重要指标之一，是最高领导权的和平更替次数以及组织能否跨越创始人世代而存活。PRI 跨越了创始人世代，也实现了每六年一次的和平更替，但每一次更替都依赖一次无法程序化的个人决断。这意味着系统的高适应性建立在一个低适应性的关节上。</p><p><strong>1988：断裂点。</strong> 卡德纳斯与穆尼奥斯·莱多等党内左翼因不满新自由主义转向而退党，另组全国民主阵线。1988 年总统大选中，卡德纳斯一度领先，随后发生了著名的计票系统&quot;瘫痪&quot;事件，萨利纳斯被宣布获胜。这次选举的争议程度，是此后所有制度改革的起点。</p><p><strong>1988—2000：从霸权党到优势党的渐进转型。</strong> 萨利纳斯任内（1988—1994）通过三次宪法修正案，改革议会席位分配方式、选举机构与选举程序；1990 年 10 月成立联邦选举研究所（IFE），这是墨西哥第一个独立于政府的选举机构。塞迪略任内的 1996 年选举改革走得更远：联邦选举法院并入司法系统，成为联邦司法系统内的选举法庭（TEPJF），同时终结了总统候选人&quot;指定制&quot;。IFE 于 2014 年被改组为国家选举研究所（INE）。</p><p>2000 年 7 月，国家行动党与绿色生态党组成的&quot;变革联盟&quot;候选人福克斯赢得大选，同年 12 月就职，PRI 失去执政权。这次更替是和平的，权力完成了移交，没有清算。</p><p><strong>这段历史给出了一个对全文极为有利的结论：可逆性机制可以在垄断地位上被部分建造，而不必等到断裂之后才获得。</strong> 我在早期稿中写&quot;可逆性是 PRI 失去垄断地位之后才获得的性质&quot;，这句话对政党轮替成立，对程序建设不成立——IFE 和 TEPJF 都是 PRI 自己在还执政时造出来的，2000 年能够和平交权靠的正是这套机制。</p><p>但这里有一个更尖锐的观察，值得单独写下来：<strong>PRI 建造这些机制，是因为它不相信自己会输。</strong> 1994 年塞迪略以约五成得票胜选；到 2000 年，同一套机构主持下的选举把它送下了台。改革序列是一次次被动让步，每一次的幅度都被校准为&quot;足以恢复选举可信度、但不足以危及本次胜选&quot;。这个校准连续成功了几轮，然后在某一轮失效了。</p><p>由此得到一个可以直接用于制度设计的推论：</p><blockquote><p><strong>让你可能被击败的那套机构，通常是由一个不相信自己会被击败的人建造的。</strong></p></blockquote><p>这句话有两面。乐观的一面是：可逆性不需要在位者有远见，它只需要在位者有短视——短视的让步累积到某个点，系统就跨过了阈值。悲观的一面是：你不能把制度设计寄托在在位者的自我约束上，因为自我约束的前提是误判，而误判不可靠。</p><h4 id="_9-2-日本自由民主党-一个诚实的降级" tabindex="-1">9.2 日本自由民主党：一个诚实的降级 <a class="header-anchor" href="#_9-2-日本自由民主党-一个诚实的降级" aria-label="Permalink to &quot;9.2 日本自由民主党：一个诚实的降级&quot;">​</a></h4><p>自民党 1955 年 11 月由自由党与民主党合并成立，此后长期执政，直到 1993 年&quot;五五年体制&quot;崩溃，持续三十八年。它的形态几乎是 PRI 的镜像：政党长期占优，但党内派阀高度组织化、公开化、长期化，学界长期把自民党描述为&quot;派阀的联邦&quot;。人事分配遵循派阀均衡原则，按各派议员人数比例分配阁僚、党内三巨头与国会委员长职位。</p><p>早期稿用这个案例支撑&quot;路线公开竞争&quot;，这个用法<strong>过强了，必须降级</strong>。自民党派阀主要是职务与资金的分配机器，不是纲领性的路线竞争体。宏池会相对偏鸽、清和政策研究会相对偏鹰，这种差异是真实的，但它在派阀运作中的权重远低于人事与献金。派阀的核心功能是：为成员分配职位、筹集与分发政治资金、在总裁选举中作为议价单位。把它当作&quot;党内路线竞争&quot;的实证，是把分配联盟误读成了纲领联盟。</p><p>降级之后，这个案例还能证明什么？三件事，其中两件比原先的说法更有用。</p><p><strong>第一，它是资金三难的活标本。</strong> 派阀依赖企业政治献金（第二条路：被资本俘获），政治世家维系人事与资金网络（第三条路：门阀化），两条路的代价都在 2023 至 2024 年的&quot;黑金&quot;丑闻中集中兑现，导致多个主要派阀解散。第六节的三难推演在这里得到了完整的经验对应。</p><p><strong>第二，它证明了政党层面的可逆性确实存在。</strong> 1993 年 6 月，众议院以 255 票对 220 票通过对宫泽内阁的不信任案，自民党羽田派三十四名议员倒戈；随后的大选中自民党未获过半席位，细川护熙组建八党联合政权，自民党自 1955 年以来首次失去政权。1994 年它与旧对手社会党联合重返执政。2009 年 8 月，民主党在众议院选举中获得 308 席，自民党仅 119 席，实现真正意义上的政权轮替。2012 年自民党大胜，安倍晋三二度组阁。两次下野，两次都回来了，而且两次都没有清算。</p><p><strong>第三，也是最关键的：它没有证明&quot;可逆路线竞争能产出更好的纠错&quot;。</strong> 因为两次下野的触发机制都不是路线竞争。1993 年的直接原因是政治资金丑闻（金丸信案）加泡沫经济崩溃，机制是派阀分裂与议员倒戈；2009 年的直接原因是长期执政疲劳加经济停滞，机制是选民惩罚。两次都是<strong>绩效惩罚</strong>，而非<strong>纲领替代</strong>。</p><h4 id="_9-3-意大利天主教民主党-一个反例-而且比正例更有用" tabindex="-1">9.3 意大利天主教民主党：一个反例，而且比正例更有用 <a class="header-anchor" href="#_9-3-意大利天主教民主党-一个反例-而且比正例更有用" aria-label="Permalink to &quot;9.3 意大利天主教民主党：一个反例，而且比正例更有用&quot;">​</a></h4><p>第九节前两小节留下一个空缺：本文找不到&quot;党内存在纲领性路线竞争，因此纠错更快更好&quot;的正面案例。这个空缺可以部分填上，但填上的方式令人不快——因为唯一符合&quot;纲领性派别&quot;这个严格标准的长期执政党，是一个失败样本。</p><p>意大利天主教民主党（DC）从 1946 年到 1994 年主导意大利政府近半个世纪，是西方民主国家中连续执政时间最长的政党之一。它的党内派别（correnti）与日本自民党的派阀有本质区别：这些派别是<strong>纲领性</strong>的。左翼的 Base 与 Forze Nuove 主张与工会接近的社会政策、反对某些右翼联盟安排；中间多数的 Dorotei 派维持平衡；还有以具体领导人命名的若干集团。派别有公开的组织机构、有自己的出版物、有自己的政策立场、并且按制度化比例（意大利政治学中的专门术语 <em>lottizzazione</em>）分配公共职位与国营企业董事席位。政府首脑在派别之间轮转，这是真实的、公开的、组织化的路线竞争。</p><p>用第六节的闸门衡量，DC 是本文全部案例中得分最高的一个：闸门二、三、四、五、六、七全部达标，而且它运行在一个完整的宪政民主框架里，闸门八、九也不成问题。</p><p>结果呢？1992 年至 1994 年的&quot;净手运动&quot;反腐调查揭开了一个规模空前的政治献金体系，DC 于 1994 年 1 月解散，改组为意大利人民党。近半个世纪的执政党在两年之内消失。</p><p>这个结局对本文的论证有三层含义，一层比一层重要。</p><p><strong>第一层，它证实了资金三难无解。</strong> DC 的派别同时走了第二条路（企业与利益集团献金）和第三条路（<em>lottizzazione</em> 把公共职位变成派别财产），两条路的代价叠加在一起，最终产生的不是慢性门阀化，而是一次总崩溃。日本的&quot;黑金&quot;丑闻导致派阀解散，但政党存活；DC 的情况是政党和派别一起消失。差别不在腐败程度，在于 DC 的派别承担了纲领功能，因此派别的道德破产直接等于政党的纲领破产。</p><p><strong>第二层，它是对第七节第二条反驳的最强实证支持。</strong> 一个拥有完整纲领性竞争机制的政党，并没有因此产出更好的纠错——它产出了更高水平的组织化分赃，而这种分赃因为有派别竞争的合法性外衣，反而更难被察觉。竞争没有让它更正确，只是让它的错误分布得更均匀。</p><p><strong>第三层，也是全文最需要面对的一点：可逆竞争机制齐备，并不能保证组织存活。</strong> 这直接冲击了本文的基本命题。如果九道闸门全部达标仍可能导向崩溃，那么闸门体系提供的到底是什么？</p><p>我的回答是：闸门体系提供的是<strong>失败之后的存续可能性</strong>，而非<strong>避免失败的能力</strong>。DC 消失了，但意大利的政治系统没有崩溃——权力和平移交给了新的政党组合，宪政框架完整，没有出现清算，没有军队介入，没有内战。用本文第四节的语言说：DC 这个<strong>政党</strong>失败了并且消失了，但失败没有变成政治生命的终结，因为消失的只是竞争者之一，而不是竞争的框架。</p><p>这个区分很重要，而且它把&quot;失败不等于消失&quot;这条原则的适用范围收窄了：<strong>在成熟的宪政框架里，被保护的不是任何特定组织，而是竞争本身。</strong> 组织可以死，竞争不能死。这也解释了为什么闸门九（最高资格可撤销）是整个体系的地基而非附加项——只有当没有任何一个组织的存续被宪法保证时，组织的死亡才不等同于系统的死亡。</p><p>所以本文诚实的结论是：<strong>找不到正面案例，而唯一的严格案例是反例。</strong> 这不能证明纲领性路线竞争无效，但它足以说明本文没有经验证据支持&quot;竞争产出更好纠错&quot;这个乐观命题，本文能支持的只是一个更弱的命题：<strong>竞争降低了纠错的暴力程度，而不必然提高纠错的质量。</strong></p><h4 id="_9-4-对照结论-错误成本的三种时间分布" tabindex="-1">9.4 对照结论：错误成本的三种时间分布 <a class="header-anchor" href="#_9-4-对照结论-错误成本的三种时间分布" aria-label="Permalink to &quot;9.4 对照结论：错误成本的三种时间分布&quot;">​</a></h4><p>三个案例对照之后，第一稿那个&quot;尖峰 vs 平台&quot;的二分不够用了，因为它把墨西哥七十一年当成一个整体。更准确的划分是三段：</p><table tabindex="0"><thead><tr><th>形态</th><th>案例</th><th>支付结构</th></tr></thead><tbody><tr><td>尖峰</td><td>PRI 1929—1988</td><td>长期不支付，一次性结清</td></tr><tr><td>被短视校准的转型</td><td>PRI 1988—2000</td><td>分期支付，但每期额度由当权者的胜选计算决定</td></tr><tr><td>平台</td><td>日本 1955 至今</td><td>每年支付小额账单，从不支付本金</td></tr><tr><td>尖峰＋崩溃</td><td>意大利 DC 1946—1994</td><td>长期支付分赃成本，最后一次性支付组织消亡</td></tr></tbody></table><p>这四行里，最有价值的不是任何一行，而是第二行的存在本身：<strong>转型可以是被短视校准出来的，而不是被远见设计出来的。</strong> PRI 在 1988 年之后并非突然获得了民主信念，它是在每一轮选举前计算&quot;这次让步多少既能恢复可信度又不危及胜选&quot;，连续算对了三轮，第四轮算错了。</p><p>这对制度设计的含义是双重的。一方面，它是好消息：可逆性机制可以在没有远见的情况下被建造出来，因为建造者的动机可以纯粹是自利的短期校准。另一方面，它是坏消息：<strong>这条路径不可复制，因为它依赖一系列恰好成立的误判。</strong> 一个计算更精确、更擅长在&quot;刚好够&quot;的边界上让步的在位者，可能永远不会跨过阈值。</p><p>而日本与意大利的对比给出另一个结论：两者都有组织化的党内竞争，差别在于竞争的载体。日本的派阀是分配联盟，政党因此存活而派阀可牺牲；DC 的派别是纲领联盟，因此派别破产即政党破产。<strong>把纲领分歧制度化到派别里，会提高竞争的质量，也会提高崩溃的连带风险。</strong> 这是一个真实的权衡，本文没有能力判断哪一边更值得。</p><p>萨托利在政党体制分类中区分&quot;霸权党体制&quot;与&quot;优势党体制&quot;，指的正是竞争是否被制度性排除。PRI 在 1988 年前属于前者，此后逐渐滑向后者；自民党与 DC 长期属于后者。这个区分比&quot;一党制／多党制&quot;有用得多，因为它把注意力从标签移到了竞争是否真实存在。</p><hr><h3 id="十、退出而非发声-部分可逆为什么不稳定" tabindex="-1">十、退出而非发声：部分可逆为什么不稳定 <a class="header-anchor" href="#十、退出而非发声-部分可逆为什么不稳定" aria-label="Permalink to &quot;十、退出而非发声：部分可逆为什么不稳定&quot;">​</a></h3><p>第九节留下两个未解释的事实。1988 年，墨西哥的纠错力量从 PRI <strong>内部出走</strong>，卡德纳斯退党另组阵线。1993 年，日本的纠错力量从自民党<strong>内部出走</strong>，羽田派三十四名议员倒戈，随后武村正义等人另组新党。两次纠错都成功了，但两次都不是通过党内竞争机制完成的，而是通过<strong>离开</strong>完成的。意大利 DC 的情况更极端：1994 年不是出走，是整个组织连同派别一起消失。</p><p>这个模式有一个现成的理论工具：赫希曼在 1970 年提出的&quot;退出、呼吁与忠诚&quot;。他的核心命题是，当一个组织内部的&quot;呼吁&quot;通道失效时，成员会转向&quot;退出&quot;；而退出会进一步削弱呼吁，因为最有能力、信息最充分、最在乎组织品质的人恰恰是最先退出的那批人。组织因此失去了自己最好的批评者，剩下的呼吁者质量更低，形成恶性循环。</p><p>把这个框架套到路线竞争上，会得到一个对第十一节的分叉点极为重要的推论：</p><blockquote><p><strong>部分可逆制不是一个稳定的中间态，它会朝一个可预测的方向退化——退化为退出。</strong></p></blockquote><p>理由是失败方的算术。如果等待有明确的、被制度保证的终点（下一次代表大会、下一次选举），那么等待是有价格的，失败方可以计算这个价格并决定忍受。如果等待没有终点，那么等待就不是一种策略，而是一种慢性死亡：干部会流失，年轻成员会转向别的通道，组织记忆会消散。在这种算术下，退出是唯一理性的选择，而退出的最佳时机恰恰是组织还掌握资源、外部还有同盟者、自己还有声望的时候——也就是在失败方最有价值的时刻。</p><p>于是发生了一件很反直觉的事：<strong>部分开放竞争的制度，会比完全不开放竞争的制度更频繁地经历分裂。</strong> 因为完全不开放时，失败方没有组织载体，无法分裂；部分开放时，失败方有了载体、有了纲领、有了支持者，但没有了终点，于是载体变成了分裂的工具。1988 年的墨西哥和 1993 年的日本都是这个模式。</p><p>这对闸门体系有一个直接的结构性结论：</p><blockquote><p><strong>闸门三、四、九不是三道独立的门，它们是一个功能单元。</strong> 受保护的少数（三）＋有保证的重返通道（四）＋可撤销的执政资格（九），三者缺一，其余两道就变成装饰。</p></blockquote><p>拆开看：有三无四，少数受保护但没有下一次，等于终身反对派；有四无九，重返通道存在但最高资格不可撤销，于是重返只在次级职位上有意义；有三有四无九，则正是赫希曼描述的那个不稳定态——组织化的少数在有天花板的系统里等待，直到等待成本超过退出成本，然后退出。</p><p>第六节把九道闸门写成一张清单，暗示可以逐条选配。这个暗示是错的。清单里至少有三个功能单元：三＋四＋九（可逆性）；六＋七（程序独立）；二＋八（竞争的真实内容与社会基础）。它们内部不可拆，单元之间也不能简单相加——因为三＋四＋九如果不建立在六＋七之上，重返通道会被程序操控掏空。</p><hr><h3 id="十一、分叉点-拒绝第九条的制度长什么样" tabindex="-1">十一、分叉点：拒绝第九条的制度长什么样 <a class="header-anchor" href="#十一、分叉点-拒绝第九条的制度长什么样" aria-label="Permalink to &quot;十一、分叉点：拒绝第九条的制度长什么样&quot;">​</a></h3><p>真正的思想实验需要有岔道。前面十节其实一直在一条单行道上滑行，每一步都必然导出下一步，这削弱了它作为实验的价值。所以现在设一个分叉：</p><blockquote><p>如果一个党接受前八道闸门，但拒绝第九道——即承认党内路线竞争、少数派保护、领导人可替换、独立选举程序、有限的司法审查、党外社会空间，但坚持国家最高执政资格不由普选决定，党的领导地位由宪法规定——这个制度长什么样？能稳定吗？</p></blockquote><p>（如第三节已说明，本节不是在为拒绝闸门九辩护，而是在描述拒绝它的人实际会得到什么。本文的规范立场是接受闸门九。）</p><p>这是一个真实存在的形态。它大致对应 PRI 在九十年代选举改革之后的状态，也部分对应新加坡人民行动党的制度组合：竞争是真实的，反对派是合法的，媒体与司法有一定独立性，社会有相当自主空间，但执政地位在可预见的时期内不可撤销。</p><p><strong>它稳定吗？</strong> 很可能稳定，而且可能稳定很久。前八道闸门足以吸收绝大多数日常冲突：路线更替在党内完成，不满通过媒体与地方选举释放，具体的行政错误通过司法救济纠正。系统内的高频纠错机制是齐全的。</p><p><strong>代价在哪里？</strong> 三处，都在低频高危的区域。</p><p>第一，当党内所有派别同时误判时，系统内没有外部纠错源。日本自民党 1993 年和 2009 年的两次下野，恰恰是党内派阀无法自我纠错时，由党外力量完成的强制重启。这个功能在有限可逆制里被切断了——因为党外力量没有制度通道去撤销执政资格。</p><p>第二，第八道闸门会随时间萎缩。党外社会保持独立性的最终意义，是它能够影响最高权力的归属。如果这个通道被永久封死，那么媒体调查、学术批评、社会组织就失去了制度性的支点，只剩下道德性的支点。道德支点会随时间衰减，这是可预期的。</p><p>第三，整个系统的重量会压在最脆弱的一环上。当执政资格不受选举检验时，宪法就成为唯一约束，而宪法的约束力又完全依赖法院的独立性。这就出现一个悖论：一个拒绝人民最终否决权的制度，反而需要一个更强、更独立的司法系统来替代它——而独立司法恰恰是最难在威权结构中长期存活的机构。</p><p>而第十节的结论让这个分叉点变得更尖锐。有限可逆制不仅&quot;纠错窗口窄&quot;，它还<strong>主动驱赶自己最好的批评者</strong>。墨西哥在 1988 年之前是相对封闭的霸权党体制，党内异议以个人形式存在；正是八十年代的部分开放，使得卡德纳斯有可能带走一整套组织资源另建政党。开放得不够，反而制造了分裂的条件。</p><p>所以本文的判断是：<strong>有限可逆制不是不稳定，而是&quot;稳定但纠错窗口窄，且会周期性地以分裂的形式支付账单&quot;。</strong> 它是一个高方差制度——日常表现可能很好，均值甚至高于某些多党民主国家，但尾部风险大，而且尾部事件的表现形式是可预测的：不是崩溃，是出走。</p><p>这个分叉点是本文与&quot;一党制必然失败&quot;论的关键区别：它承认这个中间态可行、甚至可能在很长时间里优越，但它指出优越性是有条件的，条件是系统不能遇到需要外部重启的故障，也不能遇到一批算清了等待成本的失败者。</p><hr><h3 id="十二、闸门九的精确化-谁来-说不-用什么程序说" tabindex="-1">十二、闸门九的精确化：谁来&quot;说不&quot;，用什么程序说 <a class="header-anchor" href="#十二、闸门九的精确化-谁来-说不-用什么程序说" aria-label="Permalink to &quot;十二、闸门九的精确化：谁来&quot;说不&quot;，用什么程序说&quot;">​</a></h3><p>第十一节把闸门九当作整个体系的最后保险，第六节也承认它是全文最含糊的一环。这里必须把它精确化，因为一个含糊的最高原则等于没有原则。</p><p>问题在于：&quot;人民说我们不再选择你&quot;这句话里的&quot;人民&quot;不是一个可以直接辨认的主体。第七节第三条反驳（深度分裂社会的认同政治化）恰恰指向这一点：在裂痕是单一且持久的社会里，&quot;人民&quot;会被裂痕切成两个几乎不重叠的集合，任何聚合程序都会把选举变成人口普查。</p><p>而且这里有一个更硬的技术障碍。阿罗的不可能性定理表明，在若干很弱的合理性条件下，不存在一种把个人偏好聚合为社会偏好的一般方法能同时满足全部条件。换句话说，&quot;人民的意志&quot;不是一个定义良好的对象，不同的投票规则会从完全相同的偏好分布中产出不同的结果。任何声称直接执行&quot;人民意志&quot;的制度设计，实际上都是在执行某一种聚合规则的选择，而这个选择本身是政治性的。</p><p><strong>而这把双刃剑的另一面同样锋利，必须承认：阿罗的适用范围不限于全民投票，它同样适用于党内代表大会的任何多数程序。</strong> 闸门二、四、六、七全都要靠投票产生&quot;党内多数意志&quot;。如果阿罗能消解&quot;人民&quot;，它同样消解&quot;党内多数&quot;。</p><p>本文的立场是：不主张放弃多数。多数仍是我们仅有的、可操作的裁决装置，任何替代方案（共识、协商、专家裁定）都在更大规模上遭遇同样的聚合困难。本文只主张一件事：<strong>既然任何聚合规则的选择都是政治性的，那么唯一能救它的，是让规则的选择先于竞争，且不被本轮胜者修改。</strong></p><p>这个立场同时给出了两个必须说明的限定。其一，阿罗的条件是<strong>联合施加</strong>的：不可能性来自同时要求无限制定义域、帕累托效率、非独裁与无关选项独立性。放松其中任何一条，一致的聚合规则就重新存在——最著名的是在单峰偏好下，多数规则会收敛到中位选民的偏好（布莱克与唐斯的中位选民定理）。所以阿罗定理不是&quot;民主不可能&quot;的证明，它是&quot;民主没有唯一自然形式&quot;的证明。其二，这也意味着本文第十二节下面的程序条件不是从阿罗推出的必然要求，而是一种工程选择：在明知没有唯一正确答案的情况下，选择一套事前确定的规则，好过每次都重新争论该用哪套规则。</p><p>于是闸门九的正确表述不应当是&quot;人民有权撤销执政资格&quot;，而应当是：</p><blockquote><p><strong>存在一套在竞争开始之前就已确定、且胜负双方都事前接受的程序，其结果能够导致最高执政权的转移。</strong></p></blockquote><p>这就是普热沃尔斯基所说的&quot;制度化的不确定性&quot;：结果不确定，程序确定。它不需要&quot;人民&quot;是一个统一的主体，它只需要一个所有人都同意遵守的裁定装置。用程序替代形而上学，这是制度设计能提供的最实在的东西。</p><p>要使这套程序可运转，至少需要五个具体条件：</p><ol><li><strong>程序必须先于竞争确定，而不是在竞争之后确定。</strong> 事后确定的规则等于当权者给自己写的判决书。</li><li><strong>失败方必须有法律保障的重返路径。</strong> 这是赫希曼逻辑的直接要求：没有重返路径，等待成本无穷大，退出成为唯一选项。</li><li><strong>计票与裁决机构必须独立于所有竞争方。</strong> 这正是墨西哥 1990 年的 IFE 与 1996 年的 TEPJF 所提供的东西，也是 PRI 从霸权党滑向优势党的转折点。</li><li><strong>程序本身必须被刚性保障，不能被本轮胜者以普通多数修改。</strong> 否则闸门九只是一次性的恩赐。</li><li><strong>强制力量的忠诚必须归属于程序，而非归属于任何竞争方。</strong></li></ol><p>第五条是本文最后才补上的，而它可能是最难的一条。前四条都是程序性的，但程序在最关键的时刻要靠强制力量执行——当一次选举结果被拒绝承认时，最终决定事态的不是法院的判决书，而是军队、警察和情报系统听谁的。对一个单一执政组织，这个问题格外尖锐，因为党组织与国家强制力量之间通常存在长期的人员重叠与指挥链条交织。墨西哥的案例在这里提供了一个正面材料：PRI 之所以能够把军队排除出政治，是因为革命后的军事体制被系统性地职业化并置于文官控制之下，这一过程在 1940 年代已基本完成，远早于选举改革；换句话说，第五条不是 1988 年之后才建的，它是前面所有闸门得以运转的<strong>前提</strong>。这暗示了一个不太令人愉快的顺序问题：<strong>强制力量的程序化忠诚必须先于竞争开放，而它的建立恰恰需要一个尚未面临竞争压力的在位者。</strong></p><p>前四个条件里没有一个要求&quot;人民&quot;是统一的主体。这是一个有意义的结果：它把闸门九从一个道德诉求变成了一个工程规格。</p><p>但必须承认第七节第三条反驳构成的实质限制。<strong>在社会裂痕单一且持久的条件下，闸门九可能是有害的。</strong> 如果每次最高权力竞争都沿着同一条族群、宗教或地域断层线展开，那么程序化的可撤销性会周期性地激活这条断层线，把技术性选举变成生存性对抗。在这种条件下，本文的结论不成立，甚至应当反过来说：暂缓闸门九、优先建设跨切分的社会组织，可能是更好的选择。</p><p>这不是对全文结论的削弱，而是给它加了一个适用条件。一个不知道自己在什么条件下失效的理论，是没有用处的理论。</p><hr><h3 id="十三、完备性即坍缩" tabindex="-1">十三、完备性即坍缩 <a class="header-anchor" href="#十三、完备性即坍缩" aria-label="Permalink to &quot;十三、完备性即坍缩&quot;">​</a></h3><p>现在把第九节和第十节的两个发现放在一起，会得到本文真正的结论。</p><p>发现一：如果九道闸门全部成立，那么党内就存在长期、稳定、合法、公开、组织化的竞争集团，它们能够轮流掌握最高权力，失败方保有法律保障的重返通道，而最高执政资格本身可被撤销。</p><p>发现二：具备这些性质的政治体系，在功能上就是多元竞争体系。萨托利的分类、普热沃尔斯基的定义、赫希曼的退出—呼吁机制，三者对它的描述是一致的。</p><p>于是：<strong>九道闸门若全部做到，思想实验的对象在定义上已经坍缩进了它原本要区别于的那个东西。</strong>&quot;一党&quot;成了一个历史标签，一个关于这个体系如何开始的记述，而不是一个关于它现在如何运作的判断。</p><p>亨廷顿在《变化社会中的政治秩序》里有一句话，字面上支持这个结论：&quot;就政治发展而言，重要的不是政党的数量，而是政党制度的力量和适应性。&quot;<strong>但必须说明，本文是在逆着亨廷顿的原意使用它。</strong> 在同一处论证里，亨廷顿的结论是：处于现代化之中的国家，一党制度较之多元政党体制更趋向于稳定，而从长远看两党制才是最恰当的体制。也就是说，他提出&quot;数量不重要&quot;，恰恰是为了给一党制留出辩护空间。</p><p>本文接受他的标准，但拒绝他的结论，理由是：<strong>他的适应性指标统计了和平更替的次数，却没有统计更替规则是否程序化。</strong> 亨廷顿衡量政党适应性的一个重要指标是领导层的和平世代更替，按这个指标，PRI 在 1929—1988 年间得分极高——七十一年、十余次和平更替、成功跨越创始人世代。但第九节已经说明，这些更替中的每一次都依赖一次无法程序化的个人决断。系统的高适应性建立在一个低适应性的关节上，而这个关节在 1988 年应声断裂。</p><p>所以本文对亨廷顿的修正是：<strong>适应性不应当只统计更替发生了多少次，还应当统计更替依据的规则在多大程度上独立于当权者的意志。</strong> 加上这一项，一党制在现代化中国家的稳定性优势就会显著缩水，因为它的稳定性往往集中在&quot;次数&quot;上而非&quot;规则&quot;上。</p><p>这个坍缩有两种读法，而本文原先把它们当作对立选项，这是一个范畴错误——它们其实在不同层面上。</p><p><strong>读法一是实质结论层面的：</strong> 思想实验证明了&quot;一党民主&quot;在概念上自我取消。把它做完整，它就不再是一党民主；把它做不完整，它就落入第十节描述的不稳定态。诚实的结论是放弃这个标签，直接讨论多元竞争应当采取什么形式。</p><p><strong>读法二是方法论层面的：</strong> 思想实验证明了&quot;党数&quot;从一开始就是错的问题。真正应当统计的是功能数与承担功能的组织数：有没有真实的替代方案？少数派有没有物质载体？程序控制权在谁手里？最高资格可否撤销？强制力量听谁的？这些功能可以由两个党承担，也可以由一个党内部的三个派别承担，还可以由一个党加上一个强大的党外社会共同承担。&quot;一党还是多党&quot;是问错了，&quot;这些功能由几个组织、以什么成本承担&quot;才是对的问法。</p><p>两者不冲突：读法二是关于<strong>应当怎样提问</strong>的立场，读法一是关于<strong>这个问题的答案是什么</strong>的立场。本文坚持读法二的提问方式，并且接受读法一给出的答案。</p><p>但读法一有一个必须正面回答的追问：<strong>如果结论就是&quot;换掉标签&quot;，那为什么实践中没有人换？</strong> 这不是因为人们没想明白。标签承担着起源合法性，而起源合法性无法用功能等价的另一个标签替代——你可以把一个功能上多元竞争的体系重新命名为&quot;多党制&quot;，但你无法把它的历史重写成一个多元竞争的历史，而恰恰是那段历史在提供合法性。所以标签的粘性不是认知错误，是资产锁定。</p><p>这就是&quot;标签利息&quot;的准确含义：<strong>一个在功能上是多元竞争、在名义上是一党的体系，每一天都在支付一笔翻译成本。</strong> 外部观察者要绕过标签才能理解它，内部批评者要绕过标签才能提出主张，而标签承诺的东西（统一、连续、非竞争）与它实际运作的方式（派别、轮替、竞争）相互矛盾。这笔利息通常很低，但在危机时刻会突然变得很高——当系统需要向全社会解释&quot;为什么现在的路线变了&quot;时，它没有一个与自身运作方式一致的语言可用。1981 年的历史决议之所以是高难度文件，部分原因正在这里：它要用一套否定竞争的叙事，来为一次实质上的路线更替提供合法性。</p><p>所以完备性即坍缩的完整表述是：</p><blockquote><p>闸门体系做全了，实验对象就变成了它要反对的东西；做不全，它就以分裂的形式支付差额。而无论做全还是做不全，标签都会持续收取一笔利息——这笔利息无法通过改名来消除，因为名字本身就是抵押品。</p></blockquote><hr><h3 id="十四、闸门体系的两笔未计入的代价" tabindex="-1">十四、闸门体系的两笔未计入的代价 <a class="header-anchor" href="#十四、闸门体系的两笔未计入的代价" aria-label="Permalink to &quot;十四、闸门体系的两笔未计入的代价&quot;">​</a></h3><p>在收束之前，还有两笔成本必须记入账目。它们不出现在任何一份闸门清单里，而它们可能比闸门本身更决定系统的实际表现。</p><p><strong>第一笔：强制力量的归属。</strong> 第十二节的条件五已经把它作为闸门九的运转前提提出，但它的影响远不止于此。对一个单一执政组织，&quot;谁来裁判&quot;这个问题在最后时刻常常不是由法院回答的，而是由军队、警察和情报系统的忠诚取向回答的，而这恰恰是任何程序都无法完全覆盖的领域。程序可以规定谁应当服从裁决，但程序无法保证在裁决不被服从时有人会执行它。这是闸门九无法自足之处，也是本文最没有能力给出方案的地方。墨西哥的经验（军事职业化先于选举开放）和意大利的经验（宪政框架下强制力量已完全文官化）都指向同一个顺序：<strong>这一条必须最先建成，而它最难在竞争已经开放之后再建成。</strong></p><p><strong>第二笔：派别竞争外溢到国家机器。</strong> 组织化的党内派别一旦按派分配干部，行政能力就会退化，因为职位的分配标准从能力转向了派系贡献。意大利的 <em>lottizzazione</em> 是这个名字下的经典现象：国营企业董事席位、银行行长、公共广播高层、乃至医院与大学的管理职位，都按派别比例分配。其后果不仅是腐败，更是<strong>国家能力的系统性稀释</strong>——当每一个技术性职位都是一次派系交易的成果，专业判断就失去了制度保护。日本的派阀在人事上的表现是同一现象的温和版本，PRI 的职团结构则演示了另一种形式：把社会组织收编为党的部门，代价是这些组织丧失了代表自身成员的能力，进而在八十年代社会结构变化后集体失效。</p><p>这两笔代价有一个共同的性质：<strong>它们都随时间递增，而且在递增过程中不可见。</strong> 强制力量的忠诚漂移是缓慢的，行政能力的稀释是渐进的，两者都不产生突发事件，因此都不会触发任何预警机制。一个把注意力全部放在&quot;权力交接是否和平&quot;上的制度评估，会系统性地漏掉这两项。</p><hr><h3 id="十五、结论-错误成本的时间分布" tabindex="-1">十五、结论：错误成本的时间分布 <a class="header-anchor" href="#十五、结论-错误成本的时间分布" aria-label="Permalink to &quot;十五、结论：错误成本的时间分布&quot;">​</a></h3><p>任何组织都会犯错，任何理论都有解释边界，任何领导人都受信息限制，任何时代都有自己看不见的问题。因此一个成熟的制度不应该试图解决&quot;怎样找到一个永远不会犯错的统治者&quot;，它应该解决&quot;当统治者犯错的时候，怎样让错误尽可能便宜地被纠正&quot;。</p><p>而本文全部论证最后可以压缩成一句话：<strong>不同的制度不是在选择要不要为错误付费，而是在选择什么时候付、分几次付、由谁付。</strong></p><p>第九节的四行表格就是这个问题的经验答案。墨西哥在 1929 至 1988 年间几乎不付款，然后在 1988 年之后进入一段被短视校准出来的分期支付期，每期额度由当权者的胜选计算决定，直到某一轮计算失效。日本从 1955 年起每年支付小额账单，账单内容是派阀献金丑闻、门阀化、以及 2009 至 2012 年那三年三度换相的混乱，但它在 1993 年和 2009 年两次都不必支付本金。意大利 DC 长期支付分赃成本，最后在 1994 年一次性支付了组织消亡。</p><p>这三种分布没有哪一种在总量上明显更小。差别在于形状，而形状决定了系统在什么时刻最脆弱：尖峰型在积累期末端最脆弱，平台型在每一次账单到期时都难受但从不致命，分赃型则在道德信用耗尽的那一刻同时失去一切。</p><p>至于中国 1981 年的那次纠错，它属于本文没有能力归类的第四种：一次性支付，但支付成功，而且成功依赖两笔资产——一笔不可再生（在世世代的共同记忆），一笔可再生产（此后的绩效改善）。本文第五节的判断是，这笔交易做得极好，但它的成立条件无法被制度化为可重复使用的程序。</p><p>于是最初的问题可以重新写一遍：假设一个党真诚地认为自己代表历史进步方向，真诚地认为自己没有特殊利益，也真诚地相信自己应该长期承担国家领导责任，那么它能不能建立一种民主宪政制度？</p><p>理论上完全可以进行这种制度实验。它可以不照搬美国的总统制，也不照搬其他国家的议会制，可以创造自己的制度组合。但这个实验有一条无法绕开的底线：它必须允许自己被证明错误。而&quot;允许被证明错误&quot;必须具体表现为允许路线竞争、允许少数存在、允许失败路线重新回来、允许领导人下台、允许党外社会监督、允许媒体调查、允许法院说&quot;不&quot;、允许宪法真正约束最高权力，并最终允许最高执政资格通过一套事前确定的程序被撤销。</p><p>如果做到这一点，长期执政就可以被解释为一次又一次被重新确认的结果——而这个解释的代价，是承认&quot;长期&quot;这个词已经不再承担任何规范性重量。如果永远不能接受最后一种失败，那么问题就变得非常尖锐：它究竟是在相信人民会永远选择自己，还是在认为人民无权选择别的？这两个命题看起来只差一步，实际上是两种完全不同的政治制度。</p><p>而一个政治制度真正成熟的标志也许就在这里：不是永远拥有正确答案，而是错误发生之后，不需要一次巨大的政治断裂才能重新开始。墨西哥用了七十一年等到那次断裂，而且它幸运的是断裂最终是和平的；日本用三十八年建立了一套让断裂变得不必要的机制，代价是持续不断地支付派阀政治的账单；意大利 DC 拥有一套最完整的纲领性竞争机制，结果政党和派别一起消失，但宪政框架完好无损。三条路都走通了，也都付出了它们各自最不愿意付出的那种代价。</p><p><strong>本文没有回答的问题有三个，按难度递增：</strong></p><p>第一，当党内路线竞争需要真实的物质基础，而所有已知的融资路径都会带来俘获或门阀化时，有没有第三条路？日本给出了&quot;没有&quot;的经验证据，卡特尔政党理论给出了&quot;没有&quot;的机制解释，而意大利 DC 提供了&quot;没有&quot;的最坏后果。如果这个空缺无法填上，那么第六节描述的九道闸门里，第三和第四道可能永远只能部分实现——而这会把整个体系推向第十节所描述的那个不稳定态。</p><p>第二，强制力量的程序化忠诚如何建立？本文只能指出它必须先于竞争开放，并且以墨西哥的军事职业化为例说明这是可能的，但本文给不出一个从&quot;在位者垄断强制力量&quot;到&quot;强制力量效忠于程序&quot;的转化机制。这是一个真正的空白，而它可能是全部闸门里最硬的一道。</p><p>第三，第九节那个反例如何解释？DC 拥有最完整的纲领性竞争机制，却导向了组织消亡。本文的回答是&quot;闸门体系提供失败后的存续可能性，而非避免失败的能力&quot;，但这个回答有点太方便了——它把一次组织崩溃重新描述成了框架的成功。如果崩溃的规模再大一些（比如波及整个宪政框架），同一个论证就会失效。本文没有能力说明这个论证的边界在哪里。</p><p>这是本文留下的三个最硬的问题，其中第三个最令我不安。</p><hr><h3 id="附注-本文经验性陈述与理论引用的来源" tabindex="-1">附注：本文经验性陈述与理论引用的来源 <a class="header-anchor" href="#附注-本文经验性陈述与理论引用的来源" aria-label="Permalink to &quot;附注：本文经验性陈述与理论引用的来源&quot;">​</a></h3><p><strong>墨西哥部分</strong></p><ul><li>革命制度党成立时间（1929 年 3 月 4 日）、名称沿革（国民革命党→墨西哥革命党→革命制度党）、1929—2000 年连续执政七十一年、职团主义三部门结构、总统六年任期且终身不得连任、2012—2018 年再度执政：Wikipedia &quot;Institutional Revolutionary Party&quot;；Wilson Center, &quot;El Partido Revolucionario Institucional (PRI) — Explainer&quot;；Cambridge University Press, &quot;Mexico&#39;s PRI&quot;（收于 <em>Life after Dictatorship</em>）。任期规则的宪制依据（1928 年修宪）见 &quot;Sexenio (Mexico)&quot;。</li><li>联邦选举研究所（IFE）成立于 1990 年 10 月，2014 年 4 月改组为国家选举研究所（INE）：Instituto Nacional Electoral 官方史料页；International IDEA 多媒体报告 &quot;Mexico — 1994: The Creation of the Federal Electoral Institute (IFE)&quot;；ACE Project 选举管理案例研究。</li><li>萨利纳斯任内（1988—1994）三次宪法修正案涉及议席分配、选举机构与程序：张伟《萨利纳斯执政时期（1988—1994 年）选举制度改革原因探析》，《拉丁美洲研究》2007 年第 4 期。</li><li>1996 年塞迪略任内选举改革将联邦选举法院并入司法系统（成立 TEPJF）、终结总统候选人&quot;指定制&quot;：墨西哥联邦选举法院官方文件 <em>Evolución histórica de las instituciones de la Justicia Electoral</em>；Laboratorio Electoral, &quot;La justicia electoral en México&quot;；王文仙《浅析墨西哥选举制度改革历程及其影响》，《拉丁美洲研究》2018 年第 2 期。</li><li>1988 年卡德纳斯与穆尼奥斯·莱多退党另组全国民主阵线、当年大选计票系统&quot;瘫痪&quot;事件：New Left Review, Al Giordano, &quot;Mexico&#39;s Presidential Swindle&quot;, NLR 41（2006）；S. D. Morris, &quot;Political Reformism in Mexico: Salinas at the Brink&quot;（1992）。</li><li>2000 年福克斯代表&quot;变革联盟&quot;胜选（得票约 43%）并于 12 月就职：Wikipedia &quot;2000 Mexican general election&quot;；J. L. Klesner, &quot;The End of Mexico&#39;s One-Party Regime&quot;（2001）。</li><li>1994 年塞迪略得票约五成；PRI 在 1940 年代完成军事职业化并使军队退出政治：均为公开研究中的通行叙述，本文未逐项核对精确数据与时间节点。</li></ul><p><strong>日本部分</strong></p><ul><li>自民党 1955 年 11 月由自由党与民主党合并成立；&quot;五五年体制&quot;至 1993 年崩溃；1993 年 6 月 18 日众议院以 255 票对 220 票通过对宫泽内阁的不信任案，羽田派三十四名议员倒戈；细川护熙八党联合政权；1994 年重返执政；2009 年 8 月民主党获 308 席、自民党获 119 席；2012 年安倍晋三二度组阁：Wikipedia &quot;Liberal Democratic Party (Japan)&quot;；Encyclopædia Britannica 同名词条；E. S. Krauss, &quot;The Rise and Fall of Japan&#39;s Liberal Democratic Party&quot;（2010）。</li><li>派阀均衡的人事分配原则、派阀作为&quot;派阀的联邦&quot;：K. J. Zakowski, &quot;Kōchikai of the Japanese Liberal Democratic Party and Its Significance&quot;（2011）；J. Hamzawi, &quot;Old Party, New Tricks: Candidates, Parties, and LDP Dominance in Japan&quot;（2022）。</li><li>2023—2024 年&quot;黑金&quot;丑闻导致多个主要派阀解散：为公开报道中的通行叙述，各派阀解散的具体日期本文未逐项核对。</li><li>民主党执政期间（2009—2012）首相更替与普天间基地问题、金丸信案与 1993 年下野的关联：为公开报道中的通行政治史叙述，本文仅作定性引用。</li></ul><p><strong>意大利部分</strong></p><ul><li>天主教民主党 1946—1994 年主导意大利政府、党内派别（correnti）的纲领性分歧（Base、Forze Nuove、Dorotei 等）、按派别比例分配公共职位的 <em>lottizzazione</em> 实践、1992—1994 年&quot;净手运动&quot;（Mani Pulite）反腐调查、DC 于 1994 年 1 月解散并改组为意大利人民党：以上为意大利政治史与比较政治学中的通行叙述。本文作概述性引用，<strong>未逐项核对派别名称的准确拼写、各派的政策立场细节、以及解散与改组的具体日期</strong>。派别之间的具体政策分歧在正文中仅作定性描述，读者若要引用，应另行核对专门文献（可参见 R. N. Katz 关于意大利政党体制的研究，以及 S. Gundle 与 E. Jones 关于 <em>lottizzazione</em> 的讨论）。</li><li>本节对 DC 结局的解释（&quot;派别承担纲领功能，因此派别道德破产即政党纲领破产&quot;）是本文的判断，不是任何一方的既有结论。</li></ul><p><strong>理论引用</strong></p><ul><li>卡尔·波普尔：可证伪性标准首次系统提出于 <em>Logik der Forschung</em>（1934，维也纳），英译本 <em>The Logic of Scientific Discovery</em>（1959）；政治哲学的改写见 <em>The Open Society and Its Enemies</em>（1945）；知识增长方法论的发展见 <em>Conjectures and Refutations</em>（1963）。本文第二节将可证伪性标准归于 1934 年著作，将政治改写归于 1945 年著作。</li><li>罗伯特·米歇尔斯：<em>Zur Soziologie des Parteiwesens in der modernen Demokratie</em>（1911，英译 <em>Political Parties</em>, 1915）。本文引用的是其对领导层三项控制权（组织机器运作、信息与通讯、对外代表）的分析，而非其决定论结论。</li><li>亚当·普热沃尔斯基：<em>Democracy and the Market</em>（1991）关于民主作为&quot;制度化的不确定性&quot;；&quot;Minimalist Conception of Democracy: A Defense&quot;（1999）关于民主即政党会输掉选举的制度。</li><li>理查德·卡茨与彼得·梅尔：&quot;Changing Models of Party Organization and Party Democracy: The Emergence of the Cartel Party&quot;, <em>Party Politics</em> 1(1), 1995。</li><li>阿尔伯特·赫希曼：<em>Exit, Voice, and Loyalty</em>（1970）。</li><li>乔万尼·萨托利：<em>Parties and Party Systems</em>（1976），关于霸权党体制与优势党体制的区分。</li><li>塞缪尔·亨廷顿：<em>Political Order in Changing Societies</em>（1968）。本文使用其政治制度化四维度（适应性、复杂性、自主性、内聚力），并在第十三节说明：本文引用&quot;重要的不是政党的数量而是政党制度的力量和适应性&quot;这一判断，但<strong>逆着亨廷顿本人的结论使用</strong>——亨廷顿在同一处论证处于现代化之中的国家一党制较多元政党体制更趋稳定，本文第十三节对此提出了修正（适应性指标应加入&quot;更替规则的程序化程度&quot;）。</li><li>肯尼思·阿罗：<em>Social Choice and Individual Values</em>（1951），关于不可能性定理。第十二节同时说明其条件为联合施加，并提及单峰偏好下的中位选民定理（Duncan Black, 1948；Anthony Downs, 1957）作为限定。</li><li>塞巴斯蒂安·海尔曼关于&quot;分级制政策试验&quot;（experimentation under hierarchy）的讨论：S. Heilmann, &quot;Policy Experimentation in China&#39;s Economic Rise&quot;（2008）。本文第八节对其作概述性引用，未逐条核对原文。</li><li>1976 年 10 月的政治转折与 1981 年《关于建国以来党的若干历史问题的决议》对&quot;文化大革命&quot;的定性：以决议文本为准。本文第五节对决议效果的评价（&quot;重建合法性&quot;与&quot;消耗不可再生资产&quot;两种读法，以及&quot;启动依赖记忆、维持依赖绩效&quot;的区分）是本文的判断，不是任何一方的官方表述。</li></ul>',246)])])}const c=o(n,[["render",p]]);export{h as __pageData,c as default};
